/* ═══════════════════════════════════════════════════════════════════
   SUNKUU 360 — Registro de instalaciones · B-03
   Tokens del Centro de Exportación v3: --navy #00008C · --teal #00EBC8 · --bg #EBF0F7 · --brd #D4E0EE
   ═══════════════════════════════════════════════════════════════════ */

#reg-root {
  --navy: #00008C;
  --teal: #00EBC8;
  --bg:   #EBF0F7;
  --surf: #FFFFFF;
  --pri:  #0D1B2E;
  --sec:  #5A6E8A;
  --ter:  #96AABF;
  --brd:  #D4E0EE;
  --pos:  #10B981;
  --neg:  #EF4444;
  --warn: #F59E0B;
  --shd:  0 1px 3px rgba(13,27,46,.06), 0 8px 28px rgba(13,27,46,.08);
}

#reg-root, #reg-root * { box-sizing: border-box; }

#reg-root {
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  background: var(--bg);
  color: var(--pri);
  min-height: 100%;
  display: flex;
  flex-direction: column;
}

/* ── HEADER ────────────────────────────────────────────────────────── */
#reg-header {
  background: var(--navy);
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  box-shadow: 0 2px 14px rgba(0,0,0,.32);
}
#reg-header-left  { display: flex; align-items: center; gap: 14px; }
#reg-header-right { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; justify-content: flex-end; }
#reg-logo { display: flex; align-items: center; gap: 8px; }
.brand-img { height: 22px; width: auto; display: block; }
.logo-sub  { font-weight: 400; font-size: 9px; color: rgba(255,255,255,.8); margin-left: 4px; letter-spacing: .05em; }
#reg-title { font-size: 17px; font-weight: 800; color: white; letter-spacing: -.02em; line-height: 1.1; }
#reg-subtitle { font-size: 11px; color: rgba(255,255,255,.6); margin-top: 3px; }

.modo {
  font-size: 11px; font-weight: 700; color: var(--navy);
  background: var(--teal); border-radius: 999px; padding: 4px 10px;
}
.hdr-btn {
  background: rgba(255,255,255,.08);
  border: 1px solid rgba(255,255,255,.14);
  border-radius: 8px;
  padding: 6px 12px;
  cursor: pointer;
  color: rgba(255,255,255,.8);
  font-size: 12px; font-weight: 700; font-family: inherit;
}
.hdr-btn:hover { background: rgba(255,255,255,.16); color: white; }

/* ── MENSAJE GLOBAL ────────────────────────────────────────────────── */
.reg-msg { display: none; margin: 14px 24px 0; padding: 10px 14px; border-radius: 10px; font-size: 13px; font-weight: 600; }
.reg-msg.info  { display: block; background: #EEF2FF; color: var(--navy); }
.reg-msg.error { display: block; background: #FEF2F2; color: #B91C1C; border: 1px solid #FECACA; }

/* ── BODY ──────────────────────────────────────────────────────────── */
#reg-body { padding: 20px 24px 32px; flex: 1; }
#reg-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; align-items: start; }

.reg-section {
  background: var(--surf);
  border-radius: 16px;
  border: 1px solid var(--brd);
  box-shadow: var(--shd);
  padding: 18px 20px;
  margin-bottom: 14px;
  min-width: 0;
}
.section-head { display: flex; align-items: center; gap: 10px; margin-bottom: 14px; flex-wrap: wrap; }
.sec-num {
  width: 28px; height: 28px; border-radius: 7px;
  background: linear-gradient(135deg, var(--navy), #0a0abb);
  display: flex; align-items: center; justify-content: center;
  font-size: 11px; font-weight: 800; color: var(--teal);
  flex-shrink: 0; box-shadow: 0 2px 8px rgba(0,0,140,.25);
}
.sec-title { font-size: 15px; font-weight: 800; color: var(--navy); letter-spacing: -.01em; flex: 1; }

/* ── BOTONES ───────────────────────────────────────────────────────── */
.pri-btn, .sec-btn, .mini {
  font-family: inherit; font-weight: 700; cursor: pointer; border-radius: 9px; transition: all .12s;
}
.pri-btn { background: var(--navy); color: white; border: 1px solid var(--navy); padding: 8px 16px; font-size: 13px; }
.pri-btn:hover:not(:disabled) { background: #0a0abb; }
.sec-btn { background: transparent; color: var(--navy); border: 1px solid var(--navy); padding: 8px 16px; font-size: 13px; }
.sec-btn:hover:not(:disabled) { background: rgba(0,0,140,.06); }
.pri-btn:disabled, .sec-btn:disabled { opacity: .4; cursor: not-allowed; }
.mini { background: transparent; color: var(--navy); border: 1px solid var(--brd); padding: 4px 10px; font-size: 12px; }
.mini:hover { border-color: var(--navy); }
.acciones { display: flex; gap: 10px; justify-content: flex-end; margin-top: 12px; }

/* ── TABLA ─────────────────────────────────────────────────────────── */
#reg-tabla { overflow-x: auto; }
.reg-table { width: 100%; border-collapse: collapse; font-size: 13px; }
.reg-table th {
  text-align: left; font-size: 11px; font-weight: 700; color: var(--sec);
  text-transform: uppercase; letter-spacing: .04em; padding: 6px 8px; border-bottom: 1px solid var(--brd);
}
.reg-table td { padding: 8px; border-bottom: 1px solid #EEF3F9; vertical-align: top; }
.reg-table tr.off td { color: var(--sec); }
.sub  { font-size: 11px; color: var(--sec); margin-top: 2px; }
.sub.bad { color: #B91C1C; }
.nota { font-size: 12px; color: var(--sec); margin-bottom: 10px; }
.vacio { font-size: 13px; color: var(--ter); padding: 8px 0; }

.chip { display: inline-block; font-size: 11px; font-weight: 700; border-radius: 999px; padding: 2px 8px; margin: 0 4px 2px 0; }
.chip.ok    { background: #D1FAE5; color: #065F46; }
.chip.bad   { background: #FEE2E2; color: #991B1B; }
.chip.muted { background: #E5E7EB; color: #374151; }
.chip.test  { background: #E0F2FE; color: #075985; }

/* ── FORMULARIO ────────────────────────────────────────────────────── */
.fld { display: block; margin-bottom: 12px; }
.field-label { display: block; font-size: 12px; font-weight: 600; color: var(--sec); margin-bottom: 6px; }
.inp {
  width: 100%;
  background: #F0F6FC;
  border: 1px solid var(--brd);
  border-radius: 8px;
  padding: 8px 10px;
  font-size: 13px; color: var(--pri); font-weight: 600; font-family: inherit;
}
.inp:focus { outline: none; border-color: var(--teal); }
.inp:disabled { color: var(--sec); background: #F5F7FA; }
select.inp option { color: var(--pri); background: #FFFFFF; }
.checks { display: flex; flex-direction: column; gap: 8px; margin-top: 4px; }
.chk { font-size: 13px; color: var(--pri); display: flex; align-items: center; gap: 8px; cursor: pointer; }
.chk input { accent-color: var(--navy); width: 16px; height: 16px; }

/* ── VALIDACIÓN / RESULTADO ────────────────────────────────────────── */
.box { border-radius: 10px; padding: 10px 14px; font-size: 13px; margin-bottom: 10px; line-height: 1.45; }
.box ul { margin: 6px 0 0 18px; padding: 0; }
.box.ok    { background: #ECFDF5; border: 1px solid #A7F3D0; color: #065F46; }
.box.bad   { background: #FEF2F2; border: 1px solid #FECACA; color: #991B1B; }
.box.warn  { background: #FFFBEB; border: 1px solid #FDE68A; color: #92400E; }
.box.info  { background: #EEF2FF; border: 1px solid #C7D2FE; color: #1E1B4B; }
.box.muted { background: #F3F4F6; border: 1px solid #E5E7EB; color: #374151; }

.prev { border: 1px dashed var(--brd); border-radius: 12px; padding: 12px; margin-bottom: 10px; }
.prev-t { font-size: 12px; font-weight: 800; color: var(--navy); text-transform: uppercase; letter-spacing: .04em; margin-bottom: 8px; }
.prev-c { font-size: 13px; padding: 8px 0; border-top: 1px solid #EEF3F9; }
.prev-c:first-of-type { border-top: none; }
.prev-h { font-size: 11px; font-weight: 700; color: var(--sec); margin-bottom: 3px; }

@media (max-width: 900px) {
  #reg-grid { grid-template-columns: 1fr; }
  #reg-header { flex-direction: column; align-items: flex-start; }
}

controllerScript.body:
/* Sunkuu 360 · Registro de instalaciones · B-03 (2026-10-21)
 * Widget del dashboard "Administración — Sunkuu 360" (propiedad del tenant, sin compartir). Solo TENANT_ADMIN.
 * Diseño: docs/arquitectura/2026-10-19-diseno-B.md §3. Requiere el módulo sunkuu-registro.js declarado en el editor
 * JavaScript (ícono de módulos, alias registroMod; NO en "Resources": ahí responde 401). Publica window.SunkuuRegistro
 * (catálogo de tipos, consulta Q1 y la misma validación que aplican Flota, Exportación, 3EM y Piscina).
 * Alta, edición, baja (activa=false) y "Completar" de activos "Instalación". Nunca elimina ni cambia propietarios.
 * Todas las llamadas con ctx.http. Ningún UUID fijo: customers, grupos, perfiles y dashboards salen de la API. */

/* ── PARÁMETROS ──────────────────────────────────────────────────── */
var SOLO_CLIENTES_DE_PRUEBA = true;   /* B-03/B-04: solo customers de prueba. Pasa a false en B-08 (registro real) */
var LIMITE_ACTIVOS = 100;             /* licencia PE Pilot: 100 activos */
var AVISO_ACTIVOS_LIBRES = 10;
var RE_PRUEBA = /prueba|gonex|erick/i;                    /* CLAUDE.md: entidades de prueba */
var RE_DASH_COMPARTIDO = /flota|exportaci|administraci/i; /* dashboards que no son de una instalación */
var PREFIJO_NOMBRE = 'INST · ';                            /* P-8 */
var PERFIL_ACTIVO = 'Instalación';

/* ── NÚCLEO (sin DOM; lo usan la interfaz y las pruebas node) ────── */
function crearNucleo(ctx, REG, opt) {
  opt = opt || {};
  var soloPrueba = opt.soloPrueba !== undefined ? opt.soloPrueba : SOLO_CLIENTES_DE_PRUEBA;
  var CAT = REG.CATALOGO;
  var UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  var estado = null;          /* último cargar() */
  var cacheDisp = {};         /* perfil → dispositivos */
  var cacheGrupos = null;     /* promesa de grupos de usuarios y permisos de los customers; cargar() la vacía */

  function has(o, k) { return o !== null && typeof o === 'object' && Object.prototype.hasOwnProperty.call(o, k); }
  function req(obs) {
    return new Promise(function (ok, ko) {
      obs.subscribe(function (d) { ok(d); },
                    function (e) { ko({ status: e && typeof e.status === 'number' ? e.status : 0 }); });
    });
  }
  function get(url)        { return req(ctx.http.get(url)); }
  function post(url, body) { return req(ctx.http.post(url, body)); }
  function query(body)     { return post('/api/entitiesQuery/find', body); }
  function paginas(url) {
    var out = [];
    function una(p) {
      return get(url + (url.indexOf('?') < 0 ? '?' : '&') + 'pageSize=100&page=' + p).then(function (r) {
        out = out.concat(r && r.data || []);
        return r && r.hasNext && p < 20 ? una(p + 1) : out;
      });
    }
    return una(0);
  }
  function campos(keys) { return keys.map(function (k) { return { type: 'ENTITY_FIELD', key: k }; }); }
  function val(row, grp, k) {
    var g = row.latest && row.latest[grp];
    var v = has(g, k) && g[k] ? g[k].value : null;
    return v === '' || v === undefined ? null : v;
  }
  function errHttp(que) { return function (e) { throw { mensaje: 'No se pudo ' + que + ' (HTTP ' + (e && e.status) + ').', status: e && e.status }; }; }

  /* ── Lectura del registro (Q1 cruda) ── */
  var ATRS = ['tipo', 'dashboard_id', 'dispositivos', 'etiqueta', 'ubicacion', 'orden', 'es_prueba', 'mostrar_parametros', 'activa'];

  function leerRegistro(resp, clientes) {
    var porTitulo = {};
    clientes.forEach(function (c) { porTitulo[c.title] = c; });
    var filas = (resp && resp.data || []).map(function (row) {
      var attrs = {};
      ATRS.forEach(function (k) { attrs[k] = val(row, 'SERVER_ATTRIBUTE', k); });
      var owner = val(row, 'ENTITY_FIELD', 'ownerName'), ownerType = val(row, 'ENTITY_FIELD', 'ownerType');
      var r = REG._interno.normalizar(row);
      return {
        id: row.entityId.id, name: val(row, 'ENTITY_FIELD', 'name'), label: val(row, 'ENTITY_FIELD', 'label'),
        owner: owner, ownerType: ownerType,
        clienteId: ownerType === 'CUSTOMER' && porTitulo[owner] ? porTitulo[owner].id : null,
        attrs: attrs,
        estado: r.inst ? 'valida' : (r.inactiva ? 'baja' : 'invalida'),
        motivo: r.error ? r.error.replace(/^[^:]*: /, '').replace(/^tipo desconocido \(null\)$/, 'sin tipo') : '',
        inst: r.inst || null
      };
    });
    filas.sort(function (a, b) {
      var ao = parseInt(a.attrs.orden, 10), bo = parseInt(b.attrs.orden, 10);
      if (isNaN(ao) !== isNaN(bo)) return isNaN(ao) ? 1 : -1;
      if (!isNaN(ao) && ao !== bo) return ao - bo;
      return String(a.attrs.etiqueta || a.name).localeCompare(String(b.attrs.etiqueta || b.name), 'es');
    });
    var lista = REG._interno.procesar(resp).lista;   /* exactamente lo que verán los widgets */
    return { filas: filas, lista: lista };
  }

  function cargar() {
    cacheGrupos = null;
    return Promise.all([
      query({ entityFilter: { type: 'entityType', entityType: 'CUSTOMER' }, entityFields: campos(['title', 'city', 'state']),
              pageLink: { page: 0, pageSize: 200, sortOrder: { key: { type: 'ENTITY_FIELD', key: 'title' }, direction: 'ASC' } } })
        .catch(errHttp('leer los customers')),
      query(REG._interno.buildQuery()).catch(errHttp('leer el registro de instalaciones')),
      paginas('/api/tenant/dashboards').catch(errHttp('leer los dashboards'))
    ]).then(function (r) {
      var clientes = (r[0].data || []).map(function (row) {
        var t = val(row, 'ENTITY_FIELD', 'title') || '';
        return { id: row.entityId.id, title: t, city: val(row, 'ENTITY_FIELD', 'city') || '', state: val(row, 'ENTITY_FIELD', 'state') || '',
                 prueba: RE_PRUEBA.test(t) };
      });
      var reg = leerRegistro(r[1], clientes);
      estado = { clientes: clientes, filas: reg.filas, lista: reg.lista,
                 dashboards: r[2].map(function (d) { return { id: d.id.id, title: d.title || d.name || d.id.id }; }) };
      return estado;
    });
  }

  function cliente(id) { return estado && estado.clientes.filter(function (c) { return c.id === id; })[0] || null; }
  function fila(id)    { return estado && estado.filas.filter(function (f) { return f.id === id; })[0] || null; }
  function dashboard(id) { return estado && estado.dashboards.filter(function (d) { return d.id === id; })[0] || null; }

  function parseDisp(txt) {
    if (!txt) return {};
    try { var o = typeof txt === 'string' ? JSON.parse(txt) : txt; return o && typeof o === 'object' && !Array.isArray(o) ? o : {}; }
    catch (e) { return {}; }
  }

  /* Dispositivos y dashboards ya usados por otras instalaciones (incluidas bajas e incompletas). */
  function referencias(excluirId) {
    var disp = {}, dash = {};
    estado.filas.forEach(function (f) {
      if (f.id === excluirId) return;
      var et = f.attrs.etiqueta || f.name;
      var d = parseDisp(f.attrs.dispositivos);
      Object.keys(d).forEach(function (r) { if (typeof d[r] === 'string') disp[d[r]] = et; });
      if (f.attrs.dashboard_id) dash[f.attrs.dashboard_id] = et;
    });
    return { disp: disp, dash: dash };
  }

  /* ── Listas del formulario (§3.2) ── */
  function opcionesClientes() {
    return estado.clientes.filter(function (c) { return !soloPrueba || c.prueba; });
  }
  function opcionesDashboards(assetId, dashboardActual) {
    var ref = referencias(assetId).dash;
    return estado.dashboards.filter(function (d) {
      return !ref[d.id] && !RE_DASH_COMPARTIDO.test(d.title) && d.id !== dashboardActual;
    }).sort(function (a, b) { return a.title.localeCompare(b.title, 'es'); });
  }
  function dispositivosDePerfil(perfil) {
    if (cacheDisp[perfil]) return Promise.resolve(cacheDisp[perfil]);
    return query({ entityFilter: { type: 'deviceType', deviceTypes: [perfil] }, entityFields: campos(['name', 'label', 'ownerName', 'ownerType']),
                   pageLink: { page: 0, pageSize: 200, sortOrder: { key: { type: 'ENTITY_FIELD', key: 'name' }, direction: 'ASC' } } })
      .then(function (r) {
        cacheDisp[perfil] = (r.data || []).map(function (row) {
          return { id: row.entityId.id, name: val(row, 'ENTITY_FIELD', 'name') || '', label: val(row, 'ENTITY_FIELD', 'label') || '',
                   owner: val(row, 'ENTITY_FIELD', 'ownerType') === 'CUSTOMER' ? val(row, 'ENTITY_FIELD', 'ownerName') : null };
        });
        return cacheDisp[perfil];
      }, errHttp('leer los dispositivos ' + perfil));
  }
  /* rol → dispositivos elegibles (sin los usados por otras instalaciones) */
  function opcionesDispositivos(tipo, assetId) {
    if (!has(CAT, tipo)) return Promise.resolve({});
    var roles = Object.keys(CAT[tipo].roles), ref = referencias(assetId).disp, out = {};
    return Promise.all(roles.map(function (r) {
      return dispositivosDePerfil(CAT[tipo].roles[r].perfil).then(function (l) {
        out[r] = l.filter(function (d) { return !ref[d.id]; });
      });
    })).then(function () { return out; });
  }

  function nombreDe(etiqueta) { return PREFIJO_NOMBRE + String(etiqueta || '').trim(); }
  /* Nombre del activo: en edición se conserva el actual salvo que cambie la etiqueta (P-8 solo para lo nuevo o renombrado). */
  function nombrePara(form) {
    var et = String(form.etiqueta || '').trim();
    return form.modo !== 'nuevo' && form.nombreActual && et === form.etiquetaOriginal ? form.nombreActual : nombreDe(et);
  }

  function siguienteOrden() {
    var max = 0;
    estado.filas.forEach(function (f) { var o = parseInt(f.attrs.orden, 10); if (!isNaN(o) && o > max) max = o; });
    return max + 10;
  }

  /* Valores iniciales del formulario: nuevo, o desde una fila (editar/completar). */
  function formulario(filaId) {
    var f = filaId ? fila(filaId) : null;
    if (!f) return { modo: 'nuevo', assetId: null, clienteId: '', tipo: '', dispositivos: {}, dashboardId: '', etiqueta: '',
                     ubicacion: '', orden: String(siguienteOrden()), esPrueba: true, mostrarParametros: false, activa: true, nombreActual: null, etiquetaOriginal: null };
    var a = f.attrs;
    return { modo: f.estado === 'invalida' ? 'completar' : 'editar', assetId: f.id, clienteId: f.clienteId || '',
             tipo: a.tipo && has(CAT, a.tipo) ? a.tipo : '', dispositivos: parseDisp(a.dispositivos), dashboardId: a.dashboard_id || '',
             etiqueta: a.etiqueta || f.label || '', ubicacion: a.ubicacion || '', orden: a.orden !== null ? String(a.orden) : String(siguienteOrden()),
             esPrueba: a.es_prueba !== 'false', mostrarParametros: a.mostrar_parametros === 'true', activa: a.activa !== 'false',
             nombreActual: f.name, etiquetaOriginal: String(a.etiqueta || f.label || '').trim() };
  }

  /* Propuestas al elegir customer o dashboard (§3.2). */
  function propuestaCliente(clienteId) {
    var c = cliente(clienteId);
    if (!c) return {};
    return { ubicacion: [c.city, c.state].filter(Boolean).join(', '), esPrueba: c.prueba };
  }
  function propuestaDashboard(dashboardId) {
    var d = dashboard(dashboardId);
    return d ? { etiqueta: d.title } : {};
  }

  function firma(form) {
    return JSON.stringify([form.modo, form.assetId, form.clienteId, form.tipo, form.dispositivos, form.dashboardId, String(form.etiqueta).trim(),
                           String(form.ubicacion).trim(), String(form.orden).trim(), !!form.esPrueba, !!form.mostrarParametros, !!form.activa]);
  }

  function dispositivosElegidos(form) {
    var out = {};
    if (!has(CAT, form.tipo)) return out;
    Object.keys(CAT[form.tipo].roles).forEach(function (r) {
      var v = form.dispositivos && form.dispositivos[r];
      if (v) out[r] = v;
    });
    return out;
  }

  /* ── Compartición de dashboards (§3.3-5/6): grupos de usuarios y permisos de todos los customers ── */
  /* Los grupos de usuarios y sus permisos (≈ 15 llamadas a groupPermissions) se leen en el primer Validar y se reutilizan
   * hasta el próximo cargar() (Recargar o Guardar). Los miembros de los grupos de dashboards y los usuarios se leen siempre. */
  function gruposYPermisos() {
    if (cacheGrupos) return cacheGrupos;
    var grupos = {}, permisos = {};   /* clienteId → grupos de usuarios; grupoId → permisos */
    var p = cacheGrupos = Promise.all(estado.clientes.map(function (c) {
      return get('/api/entityGroups/CUSTOMER/' + c.id + '/USER').then(function (gs) {
        grupos[c.id] = (gs || []).map(function (g) { return { id: g.id.id, name: g.name }; });
        return Promise.all(grupos[c.id].map(function (g) {
          return get('/api/userGroup/' + g.id + '/groupPermissions').then(function (ps) { permisos[g.id] = ps || []; });
        }));
      });
    })).then(function () { return { grupos: grupos, permisos: permisos }; });
    p.catch(function () { if (cacheGrupos === p) cacheGrupos = null; });   /* un error no se guarda: el siguiente Validar reintenta */
    return p;
  }
  function comparticion() {
    return gruposYPermisos().then(function (gp) {
      var grupos = gp.grupos, permisos = gp.permisos, dashGroups = {};
      Object.keys(permisos).forEach(function (g) {
        permisos[g].forEach(function (p) {
          if (p.entityGroupType === 'DASHBOARD' && p.entityGroupId) dashGroups[p.entityGroupId.id] = p.entityGroupName || p.entityGroupId.id.slice(0, 8);
        });
      });
      var miembros = {};
      return Promise.all(Object.keys(dashGroups).map(function (dg) {
        return paginas('/api/entityGroup/' + dg + '/entities').then(function (l) {
          miembros[dg] = l.map(function (e) { return e.id.id; });     /* name viene null [B-01]: títulos por /api/tenant/dashboards */
        });
      })).then(function () { return { grupos: grupos, permisos: permisos, dashGroups: dashGroups, miembros: miembros }; });
    }, errHttp('leer los grupos y permisos de los customers'));
  }

  function titulos(ids) {
    return ids.map(function (id) { var d = dashboard(id); return d ? d.title : id.slice(0, 8); })
      .sort(function (a, b) { return a.localeCompare(b, 'es'); });
  }

  /* ── Validación (§3.3). Devuelve { bloqueos, avisos, accion, existenteId, firma } ── */
  function validar(form) {
    var B = [], A = [], cli = cliente(form.clienteId), tipo = has(CAT, form.tipo) ? CAT[form.tipo] : null;
    var etiqueta = String(form.etiqueta || '').trim(), nombre = nombrePara(form);
    var disp = dispositivosElegidos(form), ref = referencias(form.assetId);
    var actual = form.assetId ? fila(form.assetId) : null;

    /* 1. Obligatorios */
    if (!cli) B.push('Elige el customer.');
    else if (soloPrueba && !cli.prueba) B.push('Modo QA: solo se pueden registrar instalaciones de customers de prueba.');
    if (actual && cli && actual.clienteId !== cli.id) B.push('El propietario no se cambia desde el formulario: es un traslado (§4 del diseño).');
    if (!tipo) B.push('Elige un tipo del catálogo.');
    if (!UUID_RE.test(form.dashboardId || '')) B.push('Elige el dashboard.');
    if (!etiqueta) B.push('La etiqueta es obligatoria.');
    if (!/^-?\d+$/.test(String(form.orden).trim())) B.push('El orden debe ser un número entero.');
    if (tipo) {
      var vistos = {};
      Object.keys(tipo.roles).forEach(function (r) {
        var id = disp[r];
        if (!id) { if (tipo.roles[r].obligatorio) B.push('Falta el dispositivo del rol "' + r + '" (' + tipo.roles[r].perfil + ').'); return; }
        if (!UUID_RE.test(id)) B.push('El dispositivo del rol "' + r + '" no es un UUID válido.');
        else if (vistos[id]) B.push('El mismo dispositivo está en los roles "' + vistos[id] + '" y "' + r + '".');
        vistos[id] = r;
      });
    }
    if (B.length) return Promise.resolve({ bloqueos: B, avisos: A, accion: null, firma: firma(form) });

    var res = { bloqueos: B, avisos: A, accion: null, existenteId: null, firma: firma(form) };

    /* 8. Nombre único (idempotencia) */
    var chkNombre = query({ entityFilter: { type: 'entityName', entityType: 'ASSET', entityNameFilter: nombre },
                            entityFields: campos(['name', 'type', 'ownerName', 'ownerType']), pageLink: { page: 0, pageSize: 50 } })
      .then(function (r) {
        var mismos = (r.data || []).filter(function (row) { return val(row, 'ENTITY_FIELD', 'name') === nombre; })
          .filter(function (row) { return row.entityId.id !== form.assetId; });
        if (form.modo !== 'nuevo') { res.accion = form.modo; res.existenteId = form.assetId; }
        if (!mismos.length) { if (form.modo === 'nuevo') res.accion = 'crear'; return; }
        var e = mismos[0], tipoE = val(e, 'ENTITY_FIELD', 'type'), dueno = val(e, 'ENTITY_FIELD', 'ownerName');
        var mismoDueno = val(e, 'ENTITY_FIELD', 'ownerType') === 'CUSTOMER' && dueno === cli.title;
        if (form.modo !== 'nuevo') { B.push('Ya existe otro activo llamado "' + nombre + '": cambia la etiqueta.'); return; }
        if (tipoE !== PERFIL_ACTIVO) { B.push('El nombre "' + nombre + '" ya lo usa un activo de perfil "' + tipoE + '".'); return; }
        if (!mismoDueno) { B.push('Ya existe "' + nombre + '" con otro propietario (' + dueno + '). No se duplica ni se traslada desde aquí.'); return; }
        var f = fila(e.entityId.id);
        res.existenteId = e.entityId.id;
        if (f && f.estado === 'invalida') {
          res.accion = 'completar';
          res.avisoAccion = '"' + nombre + '" ya existe a medias (' + (f.motivo || 'sin atributos') + '): se completará, sin crear otro activo.';
          A.push(res.avisoAccion);
        } else {
          res.accion = 'actualizar';
          res.avisoAccion = '"' + nombre + '" ya existe en este customer: se actualizarán sus atributos (no se crea otro activo).';
          A.push(res.avisoAccion);
          ref = referencias(e.entityId.id);   /* sus propios dispositivos y dashboard no cuentan como "en otra instalación" */
        }
      }, errHttp('comprobar el nombre'));

    /* El nombre va primero y, si bloquea, no se sigue: de él salen la acción (crear, completar, actualizar) y las
     * referencias propias que las comprobaciones 2–7 excluyen. Así también se evitan sus llamadas. */
    return chkNombre.then(function () {
      if (B.length) return;
      return Promise.all([
        chkDispositivos(), chkDashboard(), chkCompartir(), res.accion === 'crear' ? chkLicencia() : null
      ]);
    }).catch(function (e) {
      B.push(e && e.mensaje ? e.mensaje : 'Error inesperado al validar.');
    }).then(function () { return res; });

    /* 2–3. Dispositivos: existen, perfil, prefijo, sin otra instalación, mismo propietario */
    function chkDispositivos() {
      var ids = Object.keys(disp).map(function (r) { return disp[r]; });
      return query({ entityFilter: { type: 'entityList', entityType: 'DEVICE', entityList: ids },
                     entityFields: campos(['name', 'label', 'type', 'ownerName', 'ownerType']), pageLink: { page: 0, pageSize: 50 } })
        .then(function (r) {
          var por = {};
          (r.data || []).forEach(function (row) { por[row.entityId.id] = row; });
          Object.keys(disp).forEach(function (rol) {
            var id = disp[rol], rd = tipo.roles[rol], row = por[id];
            if (!row) { B.push('Rol "' + rol + '": el dispositivo ' + id + ' no existe.'); return; }
            var nm = val(row, 'ENTITY_FIELD', 'name') || '', perfil = val(row, 'ENTITY_FIELD', 'type');
            if (perfil !== rd.perfil) B.push('Rol "' + rol + '": ' + nm + ' es "' + perfil + '"; se espera "' + rd.perfil + '".');
            if (rd.prefijo && nm.indexOf(rd.prefijo) !== 0) B.push('Rol "' + rol + '": el nombre ' + nm + ' no empieza por "' + rd.prefijo + '".');
            if (ref.disp[id]) B.push('Rol "' + rol + '": ' + nm + ' ya está en la instalación "' + ref.disp[id] + '".');
            var ot = val(row, 'ENTITY_FIELD', 'ownerType'), on = val(row, 'ENTITY_FIELD', 'ownerName');
            if (ot !== 'CUSTOMER' || on !== cli.title)
              B.push('Rol "' + rol + '": ' + nm + ' pertenece a ' + (ot === 'CUSTOMER' ? on : 'el tenant') + ', no a ' + cli.title +
                     '. Usa "Cambiar propietario" en Dispositivos (nunca eliminar) y vuelve a validar.');
          });
        }, errHttp('leer los dispositivos elegidos'));
    }

    /* 4. Dashboard: existe, no es compartido, no está en otra instalación */
    function chkDashboard() {
      var d = dashboard(form.dashboardId);
      if (!d) { B.push('El dashboard ' + form.dashboardId + ' no existe.'); return; }
      if (RE_DASH_COMPARTIDO.test(d.title)) B.push('"' + d.title + '" es un dashboard compartido (Flota, Exportación o Administración), no de una instalación.');
      if (ref.dash[d.id]) B.push('El dashboard "' + d.title + '" ya está en la instalación "' + ref.dash[d.id] + '".');
    }

    /* 5–6. Compartición con el customer, fuga a otros customers y grupo "Customer Users" */
    function chkCompartir() {
      return comparticion().then(function (cp) {
        var mios = cp.grupos[cli.id] || [];
        var cu = mios.filter(function (g) { return g.name === 'Customer Users'; })[0];
        var ca = mios.filter(function (g) { return g.name === 'Customer Administrators'; })[0];
        if (!cu) { B.push(cli.title + ' no tiene el grupo "Customer Users".'); return; }
        var pcu = cp.permisos[cu.id] || [];
        if (!pcu.some(function (p) { return !p.entityGroupId; })) B.push('"Customer Users" de ' + cli.title + ' no tiene un rol genérico (como "Customer User"): sus usuarios no verían nada.');

        var visibles = [];
        pcu.forEach(function (p) { if (p.entityGroupType === 'DASHBOARD' && p.entityGroupId) visibles = visibles.concat(cp.miembros[p.entityGroupId.id] || []); });
        if (visibles.indexOf(form.dashboardId) < 0)
          A.push('El customer no verá este dashboard: agrégalo a su grupo de dashboards compartido con "Customer Users" (paso 4 del alta). Hoy ve: ' +
                 (visibles.length ? titulos(visibles.filter(function (x, i, a) { return a.indexOf(x) === i; })).join(', ') : 'ninguno') + '.');

        estado.clientes.forEach(function (o) {
          if (o.id === cli.id) return;
          (cp.grupos[o.id] || []).forEach(function (g) {
            (cp.permisos[g.id] || []).forEach(function (p) {
              if (p.entityGroupType === 'DASHBOARD' && p.entityGroupId && (cp.miembros[p.entityGroupId.id] || []).indexOf(form.dashboardId) >= 0)
                B.push('Fuga entre customers: el dashboard está en el grupo "' + cp.dashGroups[p.entityGroupId.id] + '", compartido con "' + g.name + '" de ' + o.title + '.');
            });
          });
        });

        return Promise.all([paginas('/api/customer/' + cli.id + '/users'),
                            cu ? paginas('/api/entityGroup/' + cu.id + '/entities') : [],
                            ca ? paginas('/api/entityGroup/' + ca.id + '/entities') : []])
          .then(function (r) {
            var en = {};
            r[1].concat(r[2]).forEach(function (e) { en[e.id.id] = true; });
            if (!r[0].length) A.push(cli.title + ' no tiene usuarios: nadie verá la instalación hasta crearlos (C).');
            r[0].forEach(function (u) {
              if (en[u.id.id]) return;
              var n = [u.firstName, u.lastName].filter(Boolean).join(' ') || u.email || u.id.id.slice(0, 8);
              A.push(n + ' no está en el grupo "Customer Users": no verá ninguna instalación.');
            });
          }, errHttp('leer los usuarios de ' + cli.title));
      });
    }

    /* 7. Licencia */
    function chkLicencia() {
      return get('/api/tenant/assets?pageSize=1&page=0').then(function (r) {
        var total = r && typeof r.totalElements === 'number' ? r.totalElements : null;
        if (total === null) { B.push('No se pudo leer el total de activos.'); return; }
        var libres = LIMITE_ACTIVOS - total;
        if (libres <= 0) B.push('Licencia: ya hay ' + total + ' de ' + LIMITE_ACTIVOS + ' activos.');
        else if (libres - 1 < AVISO_ACTIVOS_LIBRES) A.push('Licencia: tras el alta quedarán ' + (libres - 1) + ' activos libres de ' + LIMITE_ACTIVOS + '.');
      }, errHttp('leer el total de activos'));
    }
  }

  /* ── Escritura (§3.4) ── */
  function atributos(form) {
    return {
      tipo: form.tipo,
      dashboard_id: form.dashboardId,
      dispositivos: dispositivosElegidos(form),
      etiqueta: String(form.etiqueta).trim(),
      ubicacion: String(form.ubicacion || '').trim(),
      orden: parseInt(String(form.orden).trim(), 10),
      es_prueba: !!form.esPrueba,
      mostrar_parametros: !!form.mostrarParametros,
      activa: !!form.activa
    };
  }

  function guardar(form, v) {
    if (!v || v.bloqueos.length || !v.accion) return Promise.reject({ paso: 0, mensaje: 'Valida sin bloqueos antes de guardar.' });
    if (v.firma !== firma(form)) return Promise.reject({ paso: 0, mensaje: 'El formulario cambió después de validar: vuelve a validar.' });
    var cli = cliente(form.clienteId), etiqueta = String(form.etiqueta).trim(), nombre = nombrePara(form);
    var assetId = v.existenteId, creado = false, attrs = atributos(form);

    var paso1;
    if (v.accion === 'crear') {
      paso1 = Promise.all([
        get('/api/entityGroups/CUSTOMER/' + cli.id + '/ASSET').then(function (gs) {
          var all = (gs || []).filter(function (g) { return g.name === 'All'; })[0];
          if (!all) throw { mensaje: cli.title + ' no tiene grupo "All" de activos.' };
          return all.id.id;
        }),
        get('/api/assetProfileInfos?pageSize=50&page=0&textSearch=' + encodeURIComponent(PERFIL_ACTIVO)).then(function (r) {
          var p = (r && r.data || []).filter(function (x) { return x.name === PERFIL_ACTIVO; })[0];
          if (!p) throw { mensaje: 'No existe el perfil de activo "' + PERFIL_ACTIVO + '".' };
          return p.id.id;
        })
      ]).then(function (r) {
        return post('/api/asset?entityGroupId=' + r[0], { name: nombre, label: etiqueta, type: PERFIL_ACTIVO,
                                                          assetProfileId: { entityType: 'ASSET_PROFILE', id: r[1] } });
      }).then(function (a) { assetId = a.id.id; creado = true; });
    } else {
      paso1 = get('/api/asset/' + assetId).then(function (a) {
        if (!a.ownerId || a.ownerId.entityType !== 'CUSTOMER' || a.ownerId.id !== cli.id)
          throw { mensaje: 'El activo ya no pertenece a ' + cli.title + ': recarga la lista.' };
        if (a.name === nombre && a.label === etiqueta) return;
        a.name = nombre; a.label = etiqueta;             /* mismo objeto: el propietario no cambia */
        return post('/api/asset', a);
      });
    }

    return paso1.catch(function (e) {
      throw { paso: 1, mensaje: (e && e.mensaje) || ('No se pudo ' + (v.accion === 'crear' ? 'crear' : 'actualizar') + ' el activo (HTTP ' + (e && e.status) + '). No se escribió nada.') };
    }).then(function () {
      return post('/api/plugins/telemetry/ASSET/' + assetId + '/attributes/SERVER_SCOPE', attrs).catch(function (e) {
        throw { paso: 2, assetId: assetId, creado: creado,
                mensaje: 'El activo "' + nombre + '" ' + (creado ? 'se creó' : 'existe') + ' pero no se pudieron escribir sus atributos (HTTP ' + (e && e.status) +
                         '). Ningún widget lo mostrará. Usa "Completar" en la lista para terminar.' };
      });
    }).then(function () {
      return cargar().catch(function (e) {
        throw { paso: 3, assetId: assetId, mensaje: 'Se guardó, pero no se pudo releer el registro (HTTP ' + (e && e.status) + '). Recarga para comprobar.' };
      });
    }).then(function () {
      var f = fila(assetId);
      var dif = comparar(attrs, f ? f.attrs : null);
      return { assetId: assetId, accion: v.accion, creado: creado, nombre: nombre, cliente: cli.title, escrito: attrs,
               diferencias: dif, vista: vistaPrevia(f, attrs), pendientes: pendientes(v, etiqueta) };
    });
  }

  /* Releído (texto) frente a lo escrito */
  function comparar(attrs, leido) {
    if (!leido) return ['El activo no aparece en la relectura.'];
    var dif = [];
    Object.keys(attrs).forEach(function (k) {
      var w = attrs[k], r = leido[k], ok;
      if (k === 'dispositivos') {
        var o = parseDisp(r), ks = Object.keys(w).sort(), kr = Object.keys(o).sort();
        ok = ks.join() === kr.join() && ks.every(function (x) { return w[x] === o[x]; });
      } else {
        ok = (w === '' ? null : String(w)) === (r === null ? null : String(r));
      }
      if (!ok) dif.push(k + ': escrito ' + JSON.stringify(w) + ', leído ' + JSON.stringify(r));
    });
    return dif;
  }

  /* "Así lo verá cada widget" */
  function vistaPrevia(f, attrs) {
    if (!attrs.activa) return { baja: true, texto: 'Baja (activa=false): no aparece en Flota, Exportación ni en el NAV. Se conservan activo, dispositivos, telemetría y dashboard.' };
    var inst = estado.lista.filter(function (i) { return f && i.id === f.id; })[0];
    if (!inst) return { error: 'Los widgets descartarían esta instalación: ' + (f && f.motivo || 'motivo desconocido') + '.' };
    var cat = CAT[inst.tipo], ex = REG.exportacion(inst), devF = REG.dispositivoFlota(inst);
    var nombresDisp = {};
    Object.keys(cacheDisp).forEach(function (p) { cacheDisp[p].forEach(function (d) { nombresDisp[d.id] = d.label || d.name; }); });
    return {
      flota: { cliente: inst.owner, etiqueta: inst.etiqueta, tipo: cat.nombre, ubicacion: inst.ubicacion,
               dispositivo: devF ? (nombresDisp[devF] || devF) : '—', kpi: !inst.esPrueba },
      exportacion: { etiqueta: inst.etiqueta, badge: cat.nombre, variables: Object.keys(ex.varGroups).reduce(function (s, g) { return s + ex.varGroups[g].length; }, 0),
                     grupos: Object.keys(ex.varGroups).map(function (g) { return g + ' (' + ex.varGroups[g].length + ')'; }),
                     dispositivos: ex.devices.map(function (d) { return d.nombre; }) },
      nav: { opciones: REG.opcionesNav(estado.lista, inst.dashboardId).map(function (i) { return i.etiqueta; }),
             apareceEn: estado.lista.filter(function (i) { return i !== inst && REG.opcionesNav(estado.lista, i.dashboardId).indexOf(inst) >= 0; })
                                    .map(function (i) { return i.etiqueta; }) },
      parametros: inst.mostrarParametros ? 'Los usuarios del customer verán el panel de parámetros en solo lectura (FIX-02).' : 'Los usuarios del customer no ven el panel de parámetros.'
    };
  }

  function pendientes(v, etiqueta) {
    var p = ['Crear una versión manual en ThingsBoard con el tipo Activo (el auto-commit no captura atributos), p. ej. "chore(<ID>): instalación ' + etiqueta + '", y hacer git pull.',
             'Anotar la fila en CHANGELOG.md con el hash de la versión.'];
    v.avisos.forEach(function (a) { if (a !== v.avisoAccion) p.push('Resolver el aviso: ' + a); });   /* el de la acción lo resuelve el guardado */
    return p;
  }

  return {
    cargar: cargar, estado: function () { return estado; }, formulario: formulario, opcionesClientes: opcionesClientes,
    opcionesDashboards: opcionesDashboards, opcionesDispositivos: opcionesDispositivos, propuestaCliente: propuestaCliente,
    propuestaDashboard: propuestaDashboard, validar: validar, guardar: guardar, nombreDe: nombreDe, nombrePara: nombrePara, firma: firma,
    soloPrueba: soloPrueba
  };
}

/* ── INTERFAZ ────────────────────────────────────────────────────── */
