  if (N.soloPrueba) { var b = q('reg-modo'); if (b) b.style.display = ''; }

  /* ── Lista de instalaciones ── */
  function chip(t, c) { return '<span class="chip ' + c + '">' + esc(t) + '</span>'; }
  function renderTabla() {
