           '</b><div class="sub">' + esc(f.name) + '</div></td><td>' + esc(f.owner || '—') + '</td><td>' + esc(tipo) + '</td><td>' +
           esc(a.dashboard_id ? (dt[a.dashboard_id] || a.dashboard_id.slice(0, 8) + '… (no existe)') : '—') + '</td><td>' + est +
